def max_energy(beads):
    # Initialize a two-dimensional array dp to store the maximum energy obtainable for each possible sequence of merging beads
    dp = [[0] * len(beads) for _ in range(len(beads))]

    # Initialize the first row and column of dp
    for i in range(len(beads)):
        dp[0][i] = beads[i]

    # Initialize the first column of dp
    for i in range(1, len(beads)):
        dp[i][0] = beads[i]

    # Populate the rest of dp using the recurrence relation
    for i in range(1, len(beads)):
        for j in range(1, len(beads)):
            dp[i][j] = max(dp[i - 1][j - 1] + beads[j] * beads[j - 1] * beads[i], dp[i - 1][j] + beads[i])

    # Return the maximum energy obtainable
    return max(dp[-1])

def polynomial_to_string(n, coeffs):
    result = []
    for i, coeff in enumerate(coeffs):
        if coeff != 0:
            var = 'x'
            if i != n:
                var += '^' + str(n - i)
            if coeff != 1 or var != 'x':
                if coeff < 0:
                    result.append(str(coeff))
                else:
                    result.append('+' + str(coeff))
                result.append(var)
    return ''.join(result)

