def count_sequences(n: int, last: int, memo: dict) -> int:
    if n > last:
        memo[last] = 1
        return 1
    if n not in memo:
        memo[n] = 0
        for i in range(1, int(n / 2) + 1):
            memo[n] += count_sequences(i, n, memo)
    return memo[n]

def count_coprime_pairs(x0, y0):
    count = 0
    for a in range(1, y0 // x0 + 1):
        b = y0 // x0 // a
        if gcd(a, b) == 1:
            count += 1 if a == b else 2
    return count

