def next_permutation(perm):
    n = len(perm)
    if n <= 1:
        return False

    for i in range(n - 1, 0, -1):
        if perm[i] > perm[i - 1]:
            j = perm.index(perm[i - 1], i)
            perm[i - 1], perm[j] = perm[j], perm[i - 1]
            perm[j + 1:] = perm[j + 1:][::-1]
            return True

    return False

