    group_prices = []

    # Iterate through the prices list
    for i in range(0, n, 2):
        # Calculate the total price of the current group
        group_price = prices[i] + prices[i + 1]

        # If the total price is less than or equal to the limit, add it to the list
        if group_price <= w:
